{
  "anomaly_detected": true,
  "confidence": 0.99,
  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["FCC2", "NAVC2", "UART3_FCC2", "I2C3_NAVC2"],
      "pins": ["FCC2.48", "FCC2.73", "NAVC2.31", "NAVC2.47"],
      "nets": ["NET0113", "NET0034", "NET0008", "NET0175"],
      "observed": "The STM32H753 VCAP pins 48 and 73 are assigned NET0113 and NET0034, which also connect to UART3_FCC2 connector pins. The STM32F405 VCAP_1 and VCAP_2 pins are assigned NET0008 and NET0175; NET0008 also connects to the I2C3_NAVC2 connector. No required VCAP capacitors are shown on either MCU.",
      "expected": "Each MCU's VCAP pins should have the required local capacitors to ground and must not be used as interface signal nets or exposed on connector signal pins.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "FCC2 pins 48 and 73 are labeled VCAP and carry NET0113 and NET0034; UART3_FCC2 connector pins 3 and 4 carry NET0113 and NET0034. (FCC sheet, page 2; FCC Peripherals sheet, page 5)"
        },
        {
          "source": "schematic",
          "quote": "NAVC2 pins 31 and 47 are labeled VCAP_1 and VCAP_2 and carry NET0008 and NET0175; I2C3_NAVC2 connector pin 4 carries NET0008. (NAVC sheet, page 3; NAVC Peripherals sheet, page 6)"
        },
        {
          "source": "spec",
          "quote": "Flight Control Computer MCU: STM32H753VITx; Navigation Computer MCU: STM32F405RGTx. (§2 Component Table)"
        }
      ],
      "impact": "The VCAP regulator outputs are not correctly decoupled, which can prevent the MCUs from starting or operating reliably. Routing these pins onto connector signal nets also risks loading or disturbing the internal core supply.",
      "confidence": 0.99
    }
  ],
  "summary": "Both MCU VCAP networks are incorrectly routed: the FCC VCAP pins share nets with UART connector signals, and the NAVC VCAP_1 net reaches an I2C connector. Neither MCU's required VCAP capacitors are shown, risking failure or unreliable operation."
}

